#!/bin/bash
# Replace Reconstruction/<run>/ecal_<run>.{edm4hep,valtree}.root with the PID outputs regenerated by
# analysis/make_border_data_dag.py (staging: Simulation/tests/border_cut/data/<run>/). OVERWRITES files on EOS: run it
# by hand. Every run is checked first (both files present in staging, same entry count as the current valtree); if any
# run fails a check nothing is copied. The ecal_<run>.root event trees are not touched.
#
#   bash analysis/replace_reconstruction_pid.sh            # check only, prints what would be copied
#   bash analysis/replace_reconstruction_pid.sh --doit     # check, then copy
B=/eos/experiment/drdcalo/siw-ecal/TB2026-06
STAGE=${STAGE:-$B/Simulation/tests/border_cut/data}
RECO=${RECO:-$B/Reconstruction}
DOIT=0; [ "$1" = "--doit" ] && DOIT=1

source /cvmfs/sw.hsf.org/key4hep/setup.sh >/dev/null 2>&1
runs=$(ls "$STAGE")
bad=0
for r in $runs; do
  for k in edm4hep valtree; do
    [ -s "$STAGE/$r/ecal_$r.$k.root" ] || { echo "MISSING $STAGE/$r/ecal_$r.$k.root"; bad=1; }
  done
  [ -d "$RECO/$r" ] || { echo "NO RECONSTRUCTION DIR $RECO/$r"; bad=1; }
done
[ $bad = 0 ] || { echo "checks failed, nothing copied"; exit 1; }
python3 - "$STAGE" "$RECO" $runs <<'EOF' || { echo "checks failed, nothing copied"; exit 1; }
import sys, uproot
stage, reco, runs = sys.argv[1], sys.argv[2], sys.argv[3:]
bad = 0
for r in runs:
    new = uproot.open(f"{stage}/{r}/ecal_{r}.valtree.root")["ecal"]
    old = uproot.open(f"{reco}/{r}/ecal_{r}.valtree.root")["ecal"]
    ok = new.num_entries == old.num_entries and "barxy_min_border_distance" in new.keys()
    bad += not ok
    print(f"{'ok ' if ok else 'BAD'} {r}: {new.num_entries} / {old.num_entries} entries")
sys.exit(1 if bad else 0)
EOF
n=$(echo $runs | wc -w)
if [ $DOIT = 0 ]; then echo "--- $n runs pass the checks; rerun with --doit to copy them into $RECO"; exit 0; fi
for r in $runs; do
  for k in edm4hep valtree; do
    cp "$STAGE/$r/ecal_$r.$k.root" "$RECO/$r/ecal_$r.$k.root" || { echo "copy FAILED $r $k"; exit 1; }
    [ "$(stat -c %s "$STAGE/$r/ecal_$r.$k.root")" = "$(stat -c %s "$RECO/$r/ecal_$r.$k.root")" ] \
      || { echo "size mismatch $r $k"; exit 1; }
  done
  echo "replaced $r"
done
echo "--- $n runs replaced in $RECO"
